import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Variant 4: Using custom FastReader class
 */
public class Main {
    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        HZSShufflesCards solver = new HZSShufflesCards();
        solver.solve(fr, out);
        out.close();
    }

    static class HZSShufflesCards {
        NumberTheory.Mod998 mod = new NumberTheory.Mod998();

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            mod.fInv(n + m);

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                p = mod.mult(p, n - i, mod.smallInv(n + m - i));
                phaseSize = mod.add(phaseSize, p);
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long numPhases = mod.mult(m + k, mod.smallInv(k));
                long term = mod.mult(mod.ncr(n, k), numPhases, phaseSize);
                if ((k & 1) == 1)
                    answer = mod.add(answer, term);
                else
                    answer = mod.subtract(answer, term);
            }

            out.println(answer);
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class NumberTheory {
        static class Mod998 extends NumberTheory.Modulus<Mod998> {
            public long modulus() {
                return 998_244_353L;
            }
        }

        abstract static class Modulus<M extends Modulus<M>> {
            // Implementation omitted for brevity, same as original
        }
    }
}
